def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, 20.0))
        return float(min(budget, 5.0))

    my_units = 1
    total_units = my_units
    for req in opp_requirements:
        units = int(supply // req)
        if units < 1:
            units = 1
        total_units += units

    market_units = int(supply // WATER_REQ)
    if market_units < 1:
        market_units = 1

    highest_prev = max(prev_bids) if prev_bids else 95.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 95.0

    urgent = hp <= 4 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2
    scarce_day = market_units <= 1

    if critical:
        bid = max(110.0, highest_prev + 4.0)
    elif urgent and scarce_day:
        bid = max(102.0, highest_prev + 2.0)
    elif urgent:
        bid = max(90.0, avg_prev + 1.5)
    elif scarce_day:
        bid = max(97.0, highest_prev + 1.0)
    else:
        bid = 62.0
        if avg_prev < 85.0:
            bid = 68.0
        if day >= 8 and hp >= 7:
            bid = min(bid, 58.0)

    if budget < bid:
        if critical:
            return float(budget)
        bid = max(0.0, budget * 0.82)

    safe_cap = budget
    if hp >= 7 and no_water_days == 0 and not scarce_day:
        safe_cap = min(safe_cap, max(45.0, budget * 0.22))
    elif hp >= 5 and not urgent:
        safe_cap = min(safe_cap, max(70.0, budget * 0.35))

    final_bid = min(bid, safe_cap, budget)
    if critical:
        final_bid = min(max(final_bid, min(budget, highest_prev + 2.0)), budget)

    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water cheaply
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        # If no previous bids from alive opponents, use a baseline based on general competition
        highest_prev_bid = DAILY_SALARY * 0.6 # A reasonable baseline given strong opponents in meta-round

    # Calculate potential winners based on supply
    available_slots = int(day_context['supply'] // WATER_REQ)
    num_active_players = len(alive_opponents) + 1 # Me + alive opponents

    bid_amount = 0.0

    # Bidding strategy based on HP and competition
    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0: # Desperate state: Low HP or no water days
        # Bid very aggressively
        if highest_prev_bid > 0:
            bid_amount = highest_prev_bid + (DAILY_SALARY * 0.15) # Bid significantly above previous highest
        else:
            bid_amount = DAILY_SALARY * 0.95 # Very high bid if no prior bids
    elif my_status['hp'] <= 6: # Medium HP, still need to be careful
        if num_active_players > available_slots: # High competition (not enough water for all who want it)
            if highest_prev_bid > 0:
                bid_amount = highest_prev_bid + (DAILY_SALARY * 0.08) # Slightly above
            else:
                bid_amount = DAILY_SALARY * 0.8
        else: # Enough water for all or more (lower competition)
            if highest_prev_bid > 0:
                bid_amount = max(highest_prev_bid, DAILY_SALARY * 0.7) # Match or higher baseline
            else:
                bid_amount = DAILY_SALARY * 0.7
    else: # Comfortable HP
        if num_active_players > available_slots: # High competition
            if highest_prev_bid > 0:
                bid_amount = highest_prev_bid + 1.0 # Just slightly above to win
            else:
                bid_amount = DAILY_SALARY * 0.65
        else: # Enough water for all or more
            if highest_prev_bid > 0:
                # Try to win cheaply, but still above a reasonable minimum
                bid_amount = max(highest_prev_bid * 0.9, DAILY_SALARY * 0.55)
            else:
                bid_amount = DAILY_SALARY * 0.55

    # Ensure bid is at least a minimal amount to participate
    bid_amount = max(1.0, bid_amount)

    # Ensure bid does not exceed budget
    return min(my_status['budget'], bid_amount)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive = [o for o in opponents_status.values() if o['alive']]

    prev_bids = []
    for opp in alive:
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if no_water_days >= 2 or hp <= 3:
        base_bid = 0.9 * DAILY_SALARY
    elif hp > 7:
        base_bid = 0.4 * DAILY_SALARY
    else:
        base_bid = 0.6 * DAILY_SALARY

    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        target = avg_prev + 5
        if target > base_bid:
            base_bid = target

    bid = min(budget, base_bid)
    bid = max(bid, 0)
    return bid
